param()
$ErrorActionPreference='Stop';$root=$PSScriptRoot;$qpf=[double][Diagnostics.Stopwatch]::Frequency
$names=@('CPU_CLK_UNHALTED.REF_TSC','CPU_CLK_UNHALTED.THREAD','INST_RETIRED.ANY','L2_RQSTS.DEMAND_DATA_RD_MISS','L2_RQSTS.ALL_DEMAND_DATA_RD','OFFCORE_REQUESTS.L3_MISS_DEMAND_DATA_RD','OFFCORE_REQUESTS.DEMAND_DATA_RD')
function Num($s){$s=$s.Trim();if($s -notmatch '^\d[\d,]*(?:\.\d+)?$'){return [double]::NaN};[double]::Parse($s.Replace(',',''),[Globalization.CultureInfo]::InvariantCulture)}
$rows=[Collections.Generic.List[object]]::new()
foreach($cap in @('capture_d8_r4','capture_d8_revalidation_r4')){
 $dir=Join-Path $root $cap;$raw=Get-Content (Join-Path $dir 'emon_stdout.txt') -Raw;$map=@(Import-Csv (Join-Path $dir 'clock_map.csv'));$marks=@(Import-Csv (Join-Path $dir 'eviction_windows.csv'));$stdout=Get-Content (Join-Path $dir 'harness.stdout.txt') -Raw
 $ftsc=[double]([regex]::Match($stdout,'(?m)^FTSC_QPC_HZ=([0-9.]+)').Groups[1].Value);$x=[double[]]@($map|%{[double]$_.filetime_100ns});$y=[double[]]@($map|%{([double]$_.qpc_pre+[double]$_.qpc_post)/2});$xm=($x|Measure-Object -Average).Average;$ym=($y|Measure-Object -Average).Average;$num=0.;$den=0.;for($i=0;$i-lt$x.Count;$i++){$num+=($x[$i]-$xm)*($y[$i]-$ym);$den+=($x[$i]-$xm)*($x[$i]-$xm)};$slope=$num/$den;$inter=$ym-$slope*$xm;$u=.001
 $records=[Collections.Generic.List[object]]::new();foreach($chunk in [regex]::Split($raw,'(?m)^==========\s*$')){$tm=[regex]::Match($chunk,'(?m)^(\d{1,2}/\d{1,2}/\d{4}\s+\d{2}:\d{2}:\d{2}\.\d{3})\s*$');if(!$tm.Success){continue};$dt=[datetime]::ParseExact($tm.Groups[1].Value,'M/d/yyyy HH:mm:ss.fff',[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::AssumeLocal);$ev=@{};foreach($line in ($chunk -split "`r?`n")){if(!$line.Contains("`t")){continue};$f=$line -split "`t";$nm=$f[0].Trim();if($names -contains $nm){$v=[Collections.Generic.List[double]]::new();for($j=1;$j-lt$f.Count;$j++){$v.Add((Num $f[$j]))};$ev[$nm]=$v.ToArray()}};if(@($names|?{!$ev.ContainsKey($_)}).Count){continue};$t=($inter+$slope*[double]$dt.ToFileTimeUtc())/$qpf;$dur=$ev['CPU_CLK_UNHALTED.REF_TSC'][1]/$ftsc;if($dur -gt 0){$records.Add([pscustomobject]@{s=$t-$dur;e=$t;d=$dur;ev=$ev})}}
 foreach($m in $marks){$core=[int]$m.Pcore;$cond=$m.condition;$a=[double]$m.qpc_start/$qpf;$b=[double]$m.qpc_end/$qpf;$pa=[double]$m.qpc_pad_start/$qpf;$pb=[double]$m.qpc_pad_end/$qpf;$usable=@($records|?{$_.s -lt $b -and $_.e -gt $a -and $_.s-$u -ge $pa -and $_.e+$u -le $pb});$tot=@{};$even=@{};$odd=@{};foreach($n in $names){$tot[$n]=0.;$even[$n]=0.;$odd[$n]=0.};$nwin=0
  foreach($r in $usable){$nwin++;foreach($lp in @([int](2*$core),[int](2*$core+1))){foreach($nm in $names){$v=$r.ev[$nm][$lp+1];$tot[$nm]+=$v;if($lp%2 -eq 0){$even[$nm]+=$v}else{$odd[$nm]+=$v}}}}
  $sample=[regex]::Match($stdout,"(?m)^CACHE_LATENCY Pcore=$core LP=\d+ condition=$cond samples=(\d+)");$apps=if($sample.Success){[double]$sample.Groups[1].Value}else{[double]::NaN};$span=$b-$a;$req=$tot['OFFCORE_REQUESTS.DEMAND_DATA_RD'];$miss=$tot['OFFCORE_REQUESTS.L3_MISS_DEMAND_DATA_RD']
  $rows.Add([pscustomobject]@{run=if($cap -eq 'capture_d8_r4'){'Q'}else{'R'};Pcore=$core;LP_pair="$(2*$core),$(2*$core+1)";condition=if($cond -eq 'cold_shards8'){'cold'}else{'hot'};windows=$nwin;block_s=[math]::Round($span,6);apps=$apps;offcore_L3_miss_num=$miss;offcore_demand_den=$req;offcore_fraction=if($req){$miss/$req}else{[double]::NaN};offcore_per_s=$req/$span;offcore_per_application=$req/$apps;worker_L3_miss_num=$even['OFFCORE_REQUESTS.L3_MISS_DEMAND_DATA_RD'];worker_offcore_demand_den=$even['OFFCORE_REQUESTS.DEMAND_DATA_RD'];worker_offcore_per_s=$even['OFFCORE_REQUESTS.DEMAND_DATA_RD']/$span;worker_offcore_per_application=$even['OFFCORE_REQUESTS.DEMAND_DATA_RD']/$apps;sibling_L3_miss_num=$odd['OFFCORE_REQUESTS.L3_MISS_DEMAND_DATA_RD'];sibling_offcore_demand_den=$odd['OFFCORE_REQUESTS.DEMAND_DATA_RD'];sibling_offcore_per_s=$odd['OFFCORE_REQUESTS.DEMAND_DATA_RD']/$span;worker_L2_miss=$even['L2_RQSTS.DEMAND_DATA_RD_MISS'];worker_L2_demand=$even['L2_RQSTS.ALL_DEMAND_DATA_RD'];sibling_L2_miss=$odd['L2_RQSTS.DEMAND_DATA_RD_MISS'];sibling_L2_demand=$odd['L2_RQSTS.ALL_DEMAND_DATA_RD'];L2_demand_miss_num=$tot['L2_RQSTS.DEMAND_DATA_RD_MISS'];L2_demand_den=$tot['L2_RQSTS.ALL_DEMAND_DATA_RD'];INST_RETIRED=$tot['INST_RETIRED.ANY'];CPU_CLK_UNHALTED_THREAD=$tot['CPU_CLK_UNHALTED.THREAD'];CPU_CLK_UNHALTED_REF_TSC=$tot['CPU_CLK_UNHALTED.REF_TSC']})
 }
}
$out=Join-Path $root 'D8_DIAG_COUNTS_r5.csv';$rows|Export-Csv -NoTypeInformation -Encoding utf8 -LiteralPath $out;$rows|Format-Table run,Pcore,condition,offcore_L3_miss_num,offcore_demand_den,offcore_fraction,offcore_per_s,offcore_per_application,INST_RETIRED,CPU_CLK_UNHALTED_THREAD -AutoSize|Out-String -Width 300|Write-Output
